import numpy as np
# invalid input: a range below one must raise ValueError
def _probe(fn):
    try:
        fn(0.3,1.0,0.9)
        return 0
    except ValueError:
        return 1
    except Exception:
        return 2
assert np.allclose(_probe(swi_bulk_thermo), target)

